fn look_for_min(a: &[i64], i: usize) -> usize {
    // Start by assuming the minimum is at index `i`
    let mut min_idx = i;
    let mut min_val = a[i];

    // Scan the rest of the slice from i+1 to the end
    for j in (i + 1)..a.len() {
        if a[j] < min_val {
            min_val = a[j];
            min_idx = j;
        }
    }

    min_idx
}

